<?php echo form_open('payment_complements/save',['id'=>'payment-complement-create-form','class'=>'general-form']); ?><?php echo csrf_field(); ?>
<div class="modal-body clearfix"><div class="container-fluid"><div class="form-group"><label for="payment-complement-client">Cliente</label><select id="payment-complement-client" name="client_id" class="form-control select2" data-rule-required="true" required><option value="">Seleccione un cliente...</option><?php foreach($clients as$c): ?><option value="<?php echo(int)$c->id; ?>"><?php echo esc($c->company_name.($c->vat_number?' · '.$c->vat_number:'')); ?></option><?php endforeach; ?></select></div><div class="form-group"><label for="payment-complement-payment">Pago administrativo</label><select id="payment-complement-payment" name="invoice_payment_id" class="form-control select2" data-rule-required="true" required disabled><option value="">Seleccione primero un cliente...</option></select><div id="payment-candidate-help" class="text-muted mt5">El pago se habilitará después de seleccionar el cliente.</div></div></div></div>
<div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal"><i data-feather="x" class="icon-16"></i> Cancelar</button><button id="payment-complement-continue" type="submit" class="btn btn-primary" disabled><i data-feather="arrow-right-circle" class="icon-16"></i> Continuar</button></div><?php echo form_close(); ?>
<script>$(function(){var f=$('#payment-complement-create-form'),client=$('#payment-complement-client'),payment=$('#payment-complement-payment'),next=$('#payment-complement-continue'),help=$('#payment-candidate-help');f.appForm({onSuccess:function(r){if(r.redirect_url)window.location.href=r.redirect_url;}});client.add(payment).select2({dropdownParent:f.closest('.modal')});client.on('change',function(){var id=$(this).val();payment.prop('disabled',true).empty().append(new Option(id?'Cargando pagos...':'Seleccione primero un cliente...',''));next.prop('disabled',true);if(!id){help.text('El pago se habilitará después de seleccionar el cliente.');return;}$.get('<?php echo site_url('payment_complements/client'); ?>/'+id+'/payments').done(function(r){payment.empty().append(new Option('Seleccione un pago...',''));$.each(r.results||[],function(_,item){payment.append(new Option(item.text,item.id));});payment.prop('disabled',false).trigger('change.select2');help.text((r.results||[]).length?'Se muestran pagos activos sin otro Complemento vigente.':'Este cliente no tiene pagos elegibles para Complemento.');}).fail(function(){payment.empty().append(new Option('No fue posible cargar pagos',''));help.text('No fue posible consultar los pagos del cliente.');});});payment.on('change',function(){next.prop('disabled',!$(this).val());});});</script>
